def match(orders):
    trades = []

    # Book structure: bids is dict of price -> list of (id, qty, arrival_time)
    # asks is dict of price -> list of (id, qty, arrival_time)
    bids = {}  # price -> [(id, qty), ...]
    asks = {}  # price -> [(id, qty), ...]

    # Track resting orders: id -> (side, price, qty, arrival_time)
    resting = {}

    arrival_time = 0

    for order in orders:
        if order[0] == 'cancel':
            cancel_id = order[1]
            if cancel_id in resting:
                side, price, qty, _ = resting[cancel_id]
                del resting[cancel_id]

                # Remove from book
                if side == 'buy':
                    book = bids[price]
                else:
                    book = asks[price]

                book[:] = [(oid, oqty) for oid, oqty in book if oid != cancel_id]
                if not book:
                    if side == 'buy':
                        del bids[price]
                    else:
                        del asks[price]
        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            # Match the order
            remaining_qty = qty

            if side == 'buy':
                # Match against asks (lowest price first, then earliest)
                while remaining_qty > 0 and asks:
                    best_ask_price = min(asks.keys())

                    if order_type == 'limit' and price is not None and price < best_ask_price:
                        break

                    book = asks[best_ask_price]
                    sell_id, sell_qty = book[0]

                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, best_ask_price, trade_qty])

                    remaining_qty -= trade_qty

                    if trade_qty == sell_qty:
                        book.pop(0)
                        if not book:
                            del asks[best_ask_price]
                        del resting[sell_id]
                    else:
                        book[0] = (sell_id, sell_qty - trade_qty)
                        resting[sell_id] = (resting[sell_id][0], resting[sell_id][1], sell_qty - trade_qty, resting[sell_id][3])
            else:  # side == 'sell'
                # Match against bids (highest price first, then earliest)
                while remaining_qty > 0 and bids:
                    best_bid_price = max(bids.keys())

                    if order_type == 'limit' and price is not None and price > best_bid_price:
                        break

                    book = bids[best_bid_price]
                    buy_id, buy_qty = book[0]

                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, best_bid_price, trade_qty])

                    remaining_qty -= trade_qty

                    if trade_qty == buy_qty:
                        book.pop(0)
                        if not book:
                            del bids[best_bid_price]
                        del resting[buy_id]
                    else:
                        book[0] = (buy_id, buy_qty - trade_qty)
                        resting[buy_id] = (resting[buy_id][0], resting[buy_id][1], buy_qty - trade_qty, resting[buy_id][3])

            # Rest remainder if limit order and qty remains
            if remaining_qty > 0 and order_type == 'limit':
                if side == 'buy':
                    if price not in bids:
                        bids[price] = []
                    bids[price].append((order_id, remaining_qty))
                    resting[order_id] = ('buy', price, remaining_qty, arrival_time)
                else:
                    if price not in asks:
                        asks[price] = []
                    asks[price].append((order_id, remaining_qty))
                    resting[order_id] = ('sell', price, remaining_qty, arrival_time)

        arrival_time += 1

    return trades

